from pathlib import Path

home = Path('/home/ubuntu/labrkp-workforce/client/src/pages/Home.tsx')
text = home.read_text()
start = text.index('function BookingModal(')
end = text.index('\nfunction WorkerDetail(', start)
new = r'''function BookingModal({ worker, onClose }: { worker: (typeof workers)[number]; onClose: () => void }) {
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState("");
  const [service, setService] = useState(worker.services[0].name);
  const [form, setForm] = useState({ fullName: "", phone: "", email: "", date: "", time: "", location: "", notes: "", consent: false, liveEta: true });
  const selected = worker.services.find((item) => item.name === service) ?? worker.services[0];
  const update = (key: keyof typeof form, value: string | boolean) => setForm((current) => ({ ...current, [key]: value }));
  const submit = () => {
    if (!form.fullName || !form.phone || !form.email || !form.date || !form.time || !form.location || !form.consent) {
      setError("Please complete all required fields and accept the contact consent.");
      return;
    }
    const price = Number(selected.price.replace(/[^0-9]/g, ""));
    const commission = Math.round(price * 0.03);
    const request = { id: Date.now(), worker: worker.name, customer: form.fullName, service: selected.name, date: form.date, time: form.time, location: form.location, price, commission, workerEarning: price - commission, status: "Pending", liveEta: form.liveEta };
    localStorage.setItem("labrkp_pending_booking", JSON.stringify(request));
    setSubmitted(true);
  };
  if (submitted) return <div className="fixed inset-0 z-50 grid place-items-center bg-[#10201e]/60 p-4 backdrop-blur-sm"><div className="w-full max-w-md rounded-[28px] bg-white p-8 text-center shadow-2xl"><div className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-[#dff3a9] text-[#355b33]"><Check size={30} strokeWidth={2.6} /></div><p className="mt-5 text-xs font-bold uppercase tracking-[0.2em] text-[#7b8e84]">Request sent to worker</p><h2 className="mt-2 font-display text-3xl font-semibold text-[#1c2c2a]">Waiting for acceptance.</h2><p className="mx-auto mt-3 max-w-xs text-sm leading-6 text-[#65716e]">{worker.name} ko aapki booking request bhej di gayi hai. Worker accept karega to aapko status aur ETA updates milengi.</p><button onClick={onClose} className="mt-7 w-full rounded-full bg-[#243b37] py-3.5 text-sm font-semibold text-white">Back to workers</button></div></div>;
  return <div className="fixed inset-0 z-50 overflow-y-auto bg-[#10201e]/60 p-4 backdrop-blur-sm"><div className="flex min-h-full items-center justify-center py-8"><div className="w-full max-w-3xl rounded-[30px] bg-[#f8faf6] shadow-2xl"><div className="flex items-start justify-between border-b border-[#e6ebe2] px-6 py-5 sm:px-8"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#8a9993]">Book {worker.name}</p><h2 className="mt-1 font-display text-2xl font-semibold text-[#1c2c2a]">Share your details</h2></div><button onClick={onClose} className="grid h-9 w-9 place-items-center rounded-full bg-white text-[#51605a] shadow-sm"><X size={18} /></button></div><div className="m-5 rounded-2xl bg-[#fff1ea] px-4 py-3 text-sm font-semibold text-[#7d5b4e]">Customer ki details worker ko request ke saath send hongi.</div><div className="grid gap-6 p-6 pt-1 sm:grid-cols-[1fr_0.78fr] sm:p-8 sm:pt-1"><div className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><label className="block"><span className="mb-2 block text-xs font-bold uppercase tracking-[0.13em] text-[#798780]">Full name *</span><input value={form.fullName} onChange={(e) => update("fullName", e.target.value)} placeholder="Your name" className="w-full rounded-2xl border border-[#dbe4d9] bg-white px-4 py-3.5 text-sm outline-none focus:border-[#8aab62]" /></label><label className="block"><span className="mb-2 block text-xs font-bold uppercase tracking-[0.13em] text-[#798780]">Phone *</span><input value={form.phone} onChange={(e) => update("phone", e.target.value)} placeholder="03XX XXXXXXX" className="w-full rounded-2xl border border-[#dbe4d9] bg-white px-4 py-3.5 text-sm outline-none focus:border-[#8aab62]" /></label></div><label className="block"><span className="mb-2 block text-xs font-bold uppercase tracking-[0.13em] text-[#798780]">Email *</span><input type="email" value={form.email} onChange={(e) => update("email", e.target.value)} placeholder="you@example.com" className="w-full rounded-2xl border border-[#dbe4d9] bg-white px-4 py-3.5 text-sm outline-none focus:border-[#8aab62]" /></label><label className="block"><span className="mb-2 block text-xs font-bold uppercase tracking-[0.13em] text-[#798780]">Select service *</span><select value={service} onChange={(e) => setService(e.target.value)} className="w-full rounded-2xl border border-[#dbe4d9] bg-white px-4 py-3.5 text-sm outline-none focus:border-[#8aab62]">{worker.services.map((item) => <option key={item.name} value={item.name}>{item.name} · {item.price}</option>)}</select></label><div className="grid gap-4 sm:grid-cols-2"><label className="block"><span className="mb-2 block text-xs font-bold uppercase tracking-[0.13em] text-[#798780]">Date *</span><input type="date" value={form.date} onChange={(e) => update("date", e.target.value)} className="w-full rounded-2xl border border-[#dbe4d9] bg-white px-4 py-3.5 text-sm outline-none focus:border-[#8aab62]" /></label><label className="block"><span className="mb-2 block text-xs font-bold uppercase tracking-[0.13em] text-[#798780]">Time *</span><input type="time" value={form.time} onChange={(e) => update("time", e.target.value)} className="w-full rounded-2xl border border-[#dbe4d9] bg-white px-4 py-3.5 text-sm outline-none focus:border-[#8aab62]" /></label></div><label className="block"><span className="mb-2 block text-xs font-bold uppercase tracking-[0.13em] text-[#798780]">Service location *</span><textarea rows={2} value={form.location} onChange={(e) => update("location", e.target.value)} placeholder="House / office address, area and landmark" className="w-full resize-none rounded-2xl border border-[#dbe4d9] bg-white px-4 py-3.5 text-sm outline-none placeholder:text-[#a3afa9] focus:border-[#8aab62]" /></label><label className="block"><span className="mb-2 block text-xs font-bold uppercase tracking-[0.13em] text-[#798780]">Notes (optional)</span><textarea rows={2} value={form.notes} onChange={(e) => update("notes", e.target.value)} placeholder="Special request or extra details..." className="w-full resize-none rounded-2xl border border-[#dbe4d9] bg-white px-4 py-3.5 text-sm outline-none placeholder:text-[#a3afa9] focus:border-[#8aab62]" /></label><label className="flex items-start gap-3 text-sm text-[#4e6258]"><input type="checkbox" checked={form.consent} onChange={(e) => update("consent", e.target.checked)} className="mt-1 h-4 w-4 accent-[#5e824b]" /><span>I agree to be contacted about this booking request. *</span></label>{error && <p className="rounded-xl bg-[#ffe8e0] px-3 py-2 text-xs font-semibold text-[#a45843]">{error}</p>}</div><aside className="h-fit rounded-[24px] bg-[#203532] p-5 text-white"><div className="flex items-center gap-3"><img src={worker.image} alt="" className="h-12 w-12 rounded-2xl object-cover" /><div><p className="font-semibold">{worker.name}</p><p className="mt-0.5 text-xs text-white/60">{worker.city}</p></div><VerifiedMark /></div><div className="my-5 h-px bg-white/10" /><div className="space-y-3 text-sm"><div className="flex justify-between gap-4 text-white/65"><span>Service fee</span><span className="text-white">Rs. {price.toLocaleString()}</span></div><div className="flex justify-between gap-4 text-white/65"><span>Platform commission (3%)</span><span className="text-[#d8f479]">Rs. {commission.toLocaleString()}</span></div><div className="flex justify-between gap-4 border-t border-white/10 pt-3 text-white/65"><span>Worker receives</span><span className="font-semibold text-white">Rs. {(price - commission).toLocaleString()}</span></div></div><label className="mt-6 flex items-start gap-3 rounded-2xl bg-white/10 p-3 text-xs leading-5 text-white/70"><input type="checkbox" checked={form.liveEta} onChange={(e) => update("liveEta", e.target.checked)} className="mt-1 h-4 w-4 accent-[#d8f479]" />Share live ETA updates when the worker accepts and starts travelling</label><button onClick={submit} className="mt-5 flex w-full items-center justify-center gap-2 rounded-full bg-[#d7f477] py-3.5 text-sm font-bold text-[#263b31]">Send booking request <ArrowRight size={16} /></button><p className="mt-3 text-center text-[11px] leading-4 text-white/45">Payment options will appear after worker acceptance.</p></aside></div></div></div></div>;
}'''
text = text[:start] + new + text[end:]
home.write_text(text)

console = Path('/home/ubuntu/labrkp-workforce/client/src/pages/WorkerConsole.tsx')
ct = console.read_text()
ct = ct.replace('const activity = [', 'const activity = [', 1)
ct = ct.replace('export default function WorkerConsole() {\n  return', '''export default function WorkerConsole() {
  const [pendingRequest, setPendingRequest] = useState<any>(() => {
    try { return JSON.parse(localStorage.getItem("labrkp_pending_booking") || "null"); } catch { return null; }
  });
  const [requestStatus, setRequestStatus] = useState("Pending");
  const acceptRequest = () => { setRequestStatus("Accepted"); if (pendingRequest) localStorage.setItem("labrkp_pending_booking", JSON.stringify({ ...pendingRequest, status: "Accepted", eta: "20 minutes" })); };
  return''', 1)
ct = ct.replace('import { Link } from "wouter";', 'import { Link } from "wouter";\nimport { useState } from "react";', 1)
anchor = '<div className="mt-8 grid gap-5 xl:grid-cols-[1.25fr_0.75fr]">'
insert = '''{pendingRequest && <section className="mt-8 rounded-[26px] border-2 border-[#d7e9ad] bg-[#f5fbe9] p-5 sm:p-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-[#789159]">New booking request</p><h3 className="mt-1 font-display text-xl font-semibold text-[#203a34]">{pendingRequest.customer} requested {pendingRequest.service}</h3><p className="mt-2 text-sm text-[#687a6e]">{pendingRequest.date} at {pendingRequest.time} · {pendingRequest.location}</p></div><div className="flex gap-2"><button onClick={acceptRequest} disabled={requestStatus === "Accepted"} className="rounded-full bg-[#203a34] px-5 py-2.5 text-sm font-bold text-white disabled:opacity-60">{requestStatus === "Accepted" ? "Accepted" : "Accept request"}</button><button className="rounded-full border border-[#cfdcc5] bg-white px-4 py-2.5 text-sm font-bold text-[#607267]">Decline</button></div></div><div className="mt-4 flex flex-wrap gap-3 text-xs font-semibold text-[#5f7664]"><span className="rounded-full bg-white px-3 py-2">Phone: customer will be shared after acceptance</span><span className="rounded-full bg-white px-3 py-2">Fee Rs. {pendingRequest.price.toLocaleString()}</span><span className="rounded-full bg-white px-3 py-2">Your earning Rs. {pendingRequest.workerEarning.toLocaleString()}</span>{requestStatus === "Accepted" && <span className="rounded-full bg-[#d7f477] px-3 py-2 text-[#355d3d]">On the way · ETA 20 min</span>}</div></section>}
'''
if anchor not in ct: raise SystemExit('console anchor not found')
ct = ct.replace(anchor, insert + anchor, 1)
console.write_text(ct)
